<?php
function scan(array $items, bool $ok, string $s): void
{
    for ($i = 0; $ok && count($items); $i++) {}
    for ($i = 0; $i + strlen($s); $i++) {}
    for ($i = 0; $i <=> count($items); $i++) {}
    for ($i = 0, $iMax = count($items); $i != $iMax; $i++) {}
    for ($j = 0, $jMax = strlen($s); $j <= $jMax; $j++) {}
}
